# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AFET ÖNCESİ, SIRASI VE SONRASINDA YAPILMASI GEREKENLER</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Afet Öncesi Hazırlık</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• Sağlam zemine depreme</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#1e3a8a">dayanıklı binalar yapmak</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11" fill="#1e3a8a">• Dolap ve devrilebilecek</text>\n  <text x="125" y="152" text-anchor="middle" font-size="11" fill="#1e3a8a">eşyaları duvara sabitlemek</text>\n  <text x="125" y="174" text-anchor="middle" font-size="11" fill="#1e3a8a">• Aile afet planı yapmak ve</text>\n  <text x="125" y="190" text-anchor="middle" font-size="11" fill="#1e3a8a">toplanma alanını öğrenmek</text>\n  <text x="125" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• Afet çantası hazırlamak</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">2. Afet Sırası Davranışlar</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">• Sakin kalıp panik yapmamak</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• Depremde: ÇÖK - KAPAN -</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">TUTUN hareketini yapmak</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#78350f">• Pencere, balkon, merdiven ve</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11" fill="#78350f">asansörden uzak durmak</text>\n  <text x="350" y="202" text-anchor="middle" font-size="11" fill="#78350f">• Selde yüksek yerlere çıkmak</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. Afet Sonrası İlkeler</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Elektrik, su ve doğal gaz</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#14532d">vanalarını kapatmak</text>\n  <text x="575" y="136" text-anchor="middle" font-size="11" fill="#14532d">• Afet çantasını alıp güvenli</text>\n  <text x="575" y="152" text-anchor="middle" font-size="11" fill="#14532d">toplanma alanına gitmek</text>\n  <text x="575" y="174" text-anchor="middle" font-size="11" fill="#14532d">• Hasarlı binalara girmemek,</text>\n  <text x="575" y="190" text-anchor="middle" font-size="11" fill="#14532d">112 hattını meşgul etmemek</text>\n  <text x="575" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• AFAD ve Kızılay\'la iş birliği</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AFET VE ACİL DURUM ÇANTASINDA NELER BULUNMALIDIR?</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">✔ Çantada Bulunması Gerekenler</text>\n  <text x="182" y="98" text-anchor="middle" font-size="11" fill="#14532d">• Yeterli miktarda içme suyu (kişi başı en az 72 saatlik)</text>\n  <text x="182" y="118" text-anchor="middle" font-size="11" fill="#14532d">• Bozulmayan kuru gıdalar (konserve, bisküvi, kuruyemiş)</text>\n  <text x="182" y="138" text-anchor="middle" font-size="11" fill="#14532d">• İlk yardım çantası ve düzenli kullanılan ilaçlar</text>\n  <text x="182" y="158" text-anchor="middle" font-size="11" fill="#14532d">• Pilli radyo, el feneri, yedek piller ve taşınabilir şarj</text>\n  <text x="182" y="178" text-anchor="middle" font-size="11" fill="#14532d">• Sesimizi duyurmak için DÜDÜK ve çok amaçlı çakı</text>\n  <text x="182" y="198" text-anchor="middle" font-size="11" fill="#14532d">• Mevsime uygun giysi, battaniye, hijyen malzemeleri</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">• Önemli belgelerin (kimlik, tapu) fotokopisi ve nakit para</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">✘ Çantaya Konulmaması Gerekenler &amp; Bakım</text>\n  <text x="517" y="100" text-anchor="middle" font-size="11" fill="#7f1d1d">• Çabuk bozulan taze yiyecekler (süt, taze et, meyve)</text>\n  <text x="517" y="122" text-anchor="middle" font-size="11" fill="#7f1d1d">• Ağır ve gereksiz süs eşyaları, cam biblolar, ütü</text>\n  <text x="517" y="144" text-anchor="middle" font-size="11" fill="#7f1d1d">• Yanıcı ve patlayıcı maddeler, mum ve kibrit</text>\n  <text x="517" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">6 Ayda Bir Düzenli Kontrol:</text>\n  <text x="517" y="194" text-anchor="middle" font-size="11" fill="#7f1d1d">Su ve gıdaların son kullanma tarihleri, pillerin doluluğu</text>\n  <text x="517" y="214" text-anchor="middle" font-size="11" fill="#7f1d1d">ve giysilerin mevsime uygunluğu 6 ayda bir yenilenir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÖĞRENME ALANI DEĞERLENDİRMESİ: EVİMİZ DÜNYA ÖZETİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Göreceli Konum ve İlimiz</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• Bir yerin kıtalara, denizlere,</text>\n  <text x="125" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">komşulara, boğazlara ve</text>\n  <text x="125" y="134" text-anchor="middle" font-size="11" fill="#1e3a8a">yeryüzü şekillerine göre</text>\n  <text x="125" y="152" text-anchor="middle" font-size="11" fill="#1e3a8a">konumu göreceli konumdur.</text>\n  <text x="125" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• Türkiye: Asya, Avrupa ve</text>\n  <text x="125" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Afrika\'nın kesişim noktası.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">Doğal ve Beşerî Çevre</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#581c87">• Doğal Unsurlar: Dağ, ova,</text>\n  <text x="350" y="116" text-anchor="middle" font-size="11" fill="#581c87">akarsu, göl, plato, körfez</text>\n  <text x="350" y="134" text-anchor="middle" font-size="11" fill="#581c87">(İnsan eli değmeden oluşur).</text>\n  <text x="350" y="162" text-anchor="middle" font-size="11" fill="#581c87">• Beşerî Unsurlar: Köprü,</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#581c87">baraj, tünel, fabrika, liman,</text>\n  <text x="350" y="198" text-anchor="middle" font-size="11" fill="#581c87">yol ve konutlar (İnsan yapımı).</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">İklim ve Afet Türleri</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#78350f">• Karadeniz (bol yağış): Heyelan</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11" fill="#78350f">ve sel riski yüksektir.</text>\n  <text x="575" y="140" text-anchor="middle" font-size="11" fill="#78350f">• Doğu Anadolu (dik ve karlı):</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#78350f">Çığ riski yüksektir.</text>\n  <text x="575" y="180" text-anchor="middle" font-size="11" fill="#78350f">• Akdeniz ve Ege (yazı kurak):</text>\n  <text x="575" y="198" text-anchor="middle" font-size="11" fill="#78350f">Orman yangını riski yüksektir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
